custom_css:
/* 🐨字体导入 */
@import url("https://fontsapi.zeoseven.com/256/main/result.css");

/* 🐸全局变量 */
:root {
  /* 字体 */
  --font1: "Huiwen-mincho";
  --mainFontFamily: var(--font1);

  /* 颜色 */
  --color1: rgba(0, 0, 0, 1);
  --color2: rgba(255, 255, 255, 1);
  --color3: rgba(3, 44, 125, 1);
  --color4: rgba(8, 65, 201, 1);
  --color5: rgba(29, 151, 241, 1);
  --color6: rgba(2, 13, 47, 1);
  --color7: rgba(196, 199, 242, 1);
  --color8: rgba(242, 243, 248, 1);
  --color9: rgba(8, 65, 201, 0.2);
  --color10: rgba(2, 13, 47, 0.1);
  --color11: rgba(255, 255, 255, 0.3);
  --color12: rgba(255, 255, 255, 0.1);
  --color13: rgba(157, 160, 200, 1);
  --black30a: transparent;

  /* 适配 */
  /* 🐦顶栏适配 */
  --顶栏背景图宽度: 100%;
  --顶栏背景图高度: 300px;
  --顶栏背景图上下: 0px;
  --顶栏背景图左右: 0px;
  --顶栏图标大小: 20px;
  --顶栏图标宽度: 30px;
  --顶栏图标高度: 30px;
  --顶栏图标尺寸: 22px;
  --第2个顶栏图标上下: 6px;
  --第3个顶栏图标上下: 15px;
  --第4个顶栏图标上下: 0px;
  --第5个顶栏图标上下: 12px;
  --第6个顶栏图标上下: 6px;
  --第7个顶栏图标上下: 12px;
  --第8个顶栏图标上下: 5px;
  --第9个顶栏图标上下: 10px;
  --第10个顶栏图标上下: 20px;
  --第11个顶栏图标上下: 8px;
  --第12个顶栏图标上下: 9px;

  /* 🐤气泡适配 */
  --消息顶部留空: 150px;
  --气泡最小高度: 0px;
  --消息留空: 220px;
  --渐隐程度: 10px;
  --聊天区上部渐隐:linear-gradient(
  to bottom,
  transparent 0%,
  var(--color1) var(--渐隐程度),
  var(--color1) calc(100% - var(--渐隐程度)),
  transparent 100%
  );

  /* 装饰适配 */
  --顶部装饰宽度: 100%;
  --顶部装饰高度: 1000px;
  --顶部装饰上下: 100%;
  --顶部装饰左右: 0px;
  --底部装饰宽度: 100%;
  --底部装饰高度: 100px;
  --底部装饰上下: 100%;
  --底部装饰左右: 0px;

  /* 🌵头像适配 */
  --头像区域整体上下: 0px;
  --头像区域整体左右: 0px;
  --头像上下: -1px;
  --头像左右: 9%;
  --头像宽高比: 1.8;
  --头像宽度: 46%;
  --头像高度: auto;
  --头像图片位置: 50% 50%;

  /* 楼层适配 */
  --楼层上下: 9px;
  --楼层左右: 5%;
  --楼层字体大小: 9px;
  --楼层宽度: 80px;

  /* 时间适配 */
  --时间上下: 20px;
  --时间左右: 5%;
  --时间字体大小: 9px;
  --时间宽度: 100px;

  /* Token适配 */
  --Token上下: 31px;
  --Token左右: 5%;
  --Token字体大小: 9px;
  --Token宽度: 100px;

  /* 🕊️名字适配 */
  --名字上下: -30px;
  --名字左右: 6%;
  --名字字体大小: 15px;

  /* 时间戳适配 */
  --时间戳上下: 50px;
  --时间戳左右: 8%;
  --时间戳字体大小: 10px;

  /* 小幽灵适配 */
  --小幽灵宽度: 80px;
  --小幽灵高度: 80px;
  --小幽灵上下: -40px;
  --小幽灵距右: 19%;

  /* 🌿思维链适配 */
  --思维链上下: 5px;
  --思维链左右: 12%;
  --思维链宽度: 100px;
  --思维链高度: 100px;
  --思维链文字大小: 10px;

  /* ☘️按钮适配 */
  --按钮组上下: 60px;
  --按钮组左右: 7%;
  --按钮间距: 3px;
  --三个点宽度: 30px;
  --三个点高度: 30px;
  --小铅笔宽度: 30px;
  --小铅笔高度: 30px;
  --编辑时的按钮左右: 7%;
  --编辑时的按钮上下: 50px;
  --思维链按钮组上下: 95px;
  --思维链按钮组左右: 15%;
  --思维链按钮宽度: 20px;
  --思维链按钮高度: 20px;

  /* 🍹页码区适配 */
  --左箭头上下: -65px;
  --左箭头左右: 3%;
  --左箭头宽度: 50px;
  --左箭头高度: 50px;
  --右箭头上下: -63px;
  --右箭头左右: 0.7%;
  --右箭头宽度: 60px;
  --右箭头高度: 50px;
  --页码上下: 5px;
  --页码左右: 15%;
  --页码大小: 10px;

  /* 🐣文字效果适配 */
  --文字区域上边距: 80px;
  --文字区域左边距: 7%;
  --文字区域右边距: 7%;
  --文字区域下边距: 0px;
  --正文上边距: 0px;
  --正文右边距: 0px;
  --正文下边距: 0px;
  --正文左边距: 0px;

  /* 🎋底栏适配 */
  --底栏上边距: 0px;
  --底栏下边距: 0px;
  --底栏左边距: 5px;
  --底栏右边距: 5px;
  --底栏宽度: 100%;
  --底栏底部留空: 0px;
  --底栏图标间隔: 5px;
  --底栏图标大小: 25px;
  --底栏整体图标宽度: 25px;
  --底栏整体图标高度: 25px;
  --QR助手宽度: 25px;
  --QR助手高度: 25px;
  --停止图标宽度: 25px;
  --停止图标高度: 25px;
  /* 输入框适配 */
  --输入框上留空: 10px;
  --输入框下留空: 10px;
  --输入框左留空: 5px;
  --输入框右留空: 5px;
  --输入框文字: "A rose is becoming another rose at full speed.";
  --输入框文字大小: 10px;
  --输入框文字左右: 55%;
  --底栏装饰上下: 0px;
  --底栏装饰左右: 0px;
  --底栏装饰高度: 160px;
  --底栏装饰宽度: 100%;
}

/* 🐧字体使用 */
body {
  font-family: var(--font1);
  font-weight: normal;
}

/* 🐦顶栏 */
/* 去顶栏阴影 */
#top-bar {
  box-shadow: none !important;
}

/* 顶栏透明 */
body.no-blur #top-bar {
  background-color: transparent !important;
}

#top-settings-holder,
#top-settings-holder .drawer,
#top-settings-holder .drawer-toggle,
#top-settings-holder .drawer-header,
#top-bar {
  background-color: transparent !important;
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* 允许溢出 */
#top-settings-holder {
  position: relative;
  overflow: visible !important;
}

/* 顶栏背景 */
#top-settings-holder::before {
  content: "";
  position: absolute;
  width: var(--顶栏背景图宽度);
  height: var(--顶栏背景图高度);
  background-image: url("https://iili.io/qQRP1TB.png");
  background-size: 100% auto;
  background-repeat: no-repeat;
  background-position: center top;
  top: var(--顶栏背景图上下);
  left: var(--顶栏背景图左右);
  pointer-events: none;
  z-index: -2 !important;
}

/* 图标居中 */
#top-settings-holder > div {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
}

/* 原始顶栏图标大小 */
#top-settings-holder .drawer-icon::before {
  font-size: var(--顶栏图标大小);
  color: var(--color2);
}

/* 隐藏顶栏图标 */
#top-settings-holder > div >:first-child {
  background-color: transparent !important;
  box-shadow: none !important;
  border: none !important;
  /* 图标 */
  background-size: var(--顶栏图标尺寸) auto !important;
  background-repeat: no-repeat !important;
  background-position: center !important;
  /* 框大小 */
  width: var(--顶栏图标宽度) !important;
  height: var(--顶栏图标高度) !important;
  margin-top: var(--顶栏图标上下) !important;
}

#top-settings-holder .drawer-icon::before,
#top-settings-holder .drawer-icon:hover::before,
#top-settings-holder .drawer-icon:not(.closedIcon)::before {
  opacity: 0 !important;
  visibility: hidden !important;
}

/* 顶栏图标替换 */
#top-settings-holder > .drawer:nth-of-type(2) .drawer-toggle {
  background-image: url("https://iili.io/q4lRKqg.png") !important;
  margin-top: var(--第2个顶栏图标上下) !important;
  transform: scale(1.1) !important;
}

#top-settings-holder > .drawer:nth-of-type(3) .drawer-toggle {
  background-image: url("https://iili.io/q41qZ91.png") !important;
  margin-top: var(--第3个顶栏图标上下) !important;
  transform: scale(1.1) !important;
}

#top-settings-holder > .drawer:nth-of-type(4) .drawer-toggle {
  background-image: url("https://iili.io/q4GBWb9.png") !important;
  margin-top: var(--第4个顶栏图标上下) !important;
}

#top-settings-holder > .drawer:nth-of-type(5) .drawer-toggle {
  background-image: url("https://iili.io/q4Gmfln.png") !important;
  margin-top: var(--第5个顶栏图标上下) !important;
  transform: scale(1.1) !important;
}

#top-settings-holder > .drawer:nth-of-type(6) .drawer-toggle {
  background-image: url("https://iili.io/q4MNLhl.png") !important;
  margin-top: var(--第6个顶栏图标上下) !important;
  transform: scale(1.2) !important;
}

#top-settings-holder > .drawer:nth-of-type(7) .drawer-toggle {
  background-image: url("https://iili.io/q4Vu8oQ.png") !important;
  margin-top: var(--第7个顶栏图标上下) !important;
  transform: scale(0.8) !important;
}

#top-settings-holder > .drawer:nth-of-type(8) .drawer-toggle {
  background-image: url("https://iili.io/q4hfQUb.png") !important;
  margin-top: var(--第8个顶栏图标上下) !important;
  transform: scale(0.8) !important;
}

#top-settings-holder > .drawer:nth-of-type(9) .drawer-toggle {
  background-image: url("https://iili.io/q4hST2R.png") !important;
  margin-top: var(--第9个顶栏图标上下) !important;
  transform: scale(1.4) !important;
}

#top-settings-holder > .drawer:nth-of-type(10) .drawer-toggle {
  background-image: url("https://iili.io/q4j2mqg.png") !important;
  margin-top: var(--第10个顶栏图标上下) !important;
  transform: scale(1.3) !important;
}

#top-settings-holder > .drawer:nth-of-type(11) .drawer-toggle {
  background-image: url("https://iili.io/q4jvozX.png") !important;
  margin-top: var(--第11个顶栏图标上下) !important;
  transform: scale(0.7) !important;
}

#top-settings-holder > .drawer:nth-of-type(12) .drawer-toggle {
  background-image: url("https://iili.io/q4wMFPS.png") !important;
  margin-top: var(--第12个顶栏图标上下) !important;
  transform: scale(1.2) !important;
}

/* 顶栏图标悬停和选中 */
#top-settings-holder .drawer-toggle:hover,
#top-settings-holder .drawer:has(.drawer-content.openDrawer) .drawer-toggle {
  filter: drop-shadow(0 0 5px var(--color5)) !important;
}

/* 🐤聊天区域 */
/* 去聊天背景颜色 聊天居中 */
#chat {
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  box-shadow: none !important;
  /* 居中 */
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  background-color: transparent;
}

/* 聊天上部渐隐 */
#chat {
  -webkit-mask-image: var(--聊天区上部渐隐) !important;
  mask-image: var(--聊天区上部渐隐) !important;
}

/* 消息顶部留空 */
.mes {
  top: var(--消息顶部留空);
  position: relative !important;
  z-index: 0;
  isolation: isolate;
}

/* 消息留空 */
.mes + .mes {
  margin-top: var(--消息留空);
}

/* 气泡 */
.mes {
  background-image:url("https://iili.io/q6PNhiB.png"),
  url("https://iili.io/q4gZYxV.png");
  background-repeat: no-repeat, repeat-y;
  background-position: top center, top center;
  background-size: 100% auto, 100% auto;
  width: 100%;
  margin-bottom: 0;
  overflow: visible;
  border-radius: 0px !important;
  box-shadow: none !important;
  border: none !important;
}

/* 顶部装饰 */
.mes::before {
  content: "";
  position: absolute !important;
  background-image: url("https://iili.io/q6PW5bV.png");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: bottom center;
  width: var(--顶部装饰宽度);
  height: var(--顶部装饰高度);
  bottom: var(--顶部装饰上下);
  left: var(--顶部装饰左右);
  right: var(--顶部装饰左右);
  pointer-events: none;
  z-index: 2 !important;
}

/* 底部装饰 */
.mes::after {
  content: "";
  position: absolute !important;
  background-image: url("https://iili.io/qQH5Vkv.png");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: top center;
  width: var(--底部装饰宽度);
  height: var(--底部装饰高度);
  top: var(--底部装饰上下);
  left: var(--底部装饰左右);
  right: var(--底部装饰左右);
  pointer-events: none;
  z-index: 2 !important;
}

/* 头像区域整体 */
.mesAvatarWrapper {
  position: absolute !important;
  top: var(--头像区域整体上下) !important;
  left: var(--头像区域整体左右) !important;
  right: 0 !important;
  width: 100% !important;
  margin: 0 !important;
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: flex-start !important;
  flex-wrap: nowrap !important;
  height: auto !important;
}

/* 头像 */
.mesAvatarWrapper .avatar {
  position: absolute !important;
  top: var(--头像上下) !important;
  transform: translateY(-100%) !important;
  left: var(--头像左右) !important;
  border-radius: 0 !important;
  border: 0px !important;
  width: var(--头像宽度) !important;
  height: var(--头像高度) !important;
  aspect-ratio: var(--头像宽高比) / 1;
  overflow: visible !important;
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  filter: grayscale(0%) !important;
  z-index: 1 !important;
}

/* 头像图片 */
.mesAvatarWrapper .avatar img {
  border: 0px !important;
  border-radius: 0px !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
  object-position: var(--头像图片位置) !important;
  box-shadow: none !important;
}

/* 气泡最小高度 */
.mes {
  min-height: var(--气泡最小高度) !important; /* 气泡最小高度 */
  height: auto !important;
  flex: 0 0 auto !important; /* 高度由内容决定 */
}

/* 楼层 */
.mesAvatarWrapper .mesIDDisplay {
  position: absolute !important;
  top: var(--楼层上下) !important;
  right: var(--楼层左右) !important;
  box-sizing: border-box !important;
  padding: 0 !important;
  text-shadow: none !important;
  background: transparent !important;
  margin: 0 !important;
  line-height: 1 !important;
  font-weight: normal !important;
  opacity: 1 !important;
  text-align: right !important;
  width: auto;
  white-space: nowrap !important;
  font-size: var(--楼层字体大小) !important;
  z-index: 3 !important;
}

/* 时间 */
.mesAvatarWrapper .mes_timer {
  position: absolute !important;
  top: var(--时间上下) !important;
  right: var(--时间左右) !important;
  width: auto !important;
  box-sizing: border-box !important;
  text-shadow: none !important;
  margin: 0 !important;
  padding: 0 !important;
  line-height: 1 !important;
  font-weight: normal !important;
  opacity: 1 !important;
  text-align: right !important;
  white-space: nowrap !important;
  font-size: var(--时间字体大小) !important;
  z-index: 3 !important;
}

/* Token */
.mesAvatarWrapper .tokenCounterDisplay {
  position: absolute !important;
  font-family: var(--font2) !important;
  top: var(--Token上下) !important;
  right: var(--Token左右) !important;
  width: auto !important;
  box-sizing: border-box !important;
  text-shadow: none !important;
  margin: 0 !important;
  padding: 0 !important;
  line-height: 1 !important;
  font-weight: normal !important;
  opacity: 1 !important;
  text-align: right !important;
  white-space: nowrap !important;
  font-size: var(--Token字体大小) !important;
  z-index: 3 !important;
}

/* 🕊️名字和时间戳 */
/* 名字和时间戳（一般来说别动） */
.mes .ch_name.flex-container {
  position: absolute !important;
  top: 0px !important;
  left: 0px !important;
  right: 0 !important;
  width: 100% !important;
  margin: 0 !important;
  justify-content: flex-start !important;
  align-items: flex-start !important;
}

/* 名字 */
.mes .ch_name.flex-container .name_text {
  text-shadow: none !important;
  font-weight: normal !important;
  font-style: normal !important;
  text-decoration: none !important;
  letter-spacing: normal !important;
  font-size: var(--名字字体大小) !important;
  position: absolute !important;
  top: var(--名字上下) !important;
  right: var(--名字左右) !important;
  margin: 0 !important;
  padding: 0 8px 0 0 !important;
  display: inline-block !important;
  height: auto !important;
  opacity: 1 !important;
  white-space: nowrap !important;
  text-align: right !important;
  width: auto;
  z-index: 3 !important;
}

/* 时间戳 */
.mes .ch_name.flex-container .timestamp {
  position: absolute !important;
  text-shadow: none !important;
  font-weight: normal !important;
  font-style: normal !important;
  text-decoration: none !important;
  letter-spacing: normal !important;
  font-size: var(--时间戳字体大小) !important;
  position: absolute !important;
  top: var(--时间戳上下) !important;
  right: var(--时间戳左右) !important;
  width: auto;
  display: inline-block !important;
  opacity: 1 !important;
  text-align: right !important;
}

/* 小幽灵 */
.mes_ghost.fa-ghost[title][data-i18n] {
  position: absolute !important;
  right: var(--小幽灵距右) !important;
  margin-left: 0 !important;
  width: var(--小幽灵宽度) !important;
  height: var(--小幽灵高度) !important;
  transform: translateY(var(--小幽灵上下)) !important;
  color: transparent !important;
  background-image: url("https://iili.io/q6DiJNs.png");
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  z-index: 3 !important;
}

/* 思维链按钮 */
.mes_reasoning_header.flex-container {
  /* 位置 */
  position: absolute !important;
  color: var(--color7) !important;
  top: var(--思维链上下) !important;
  left: var(--思维链左右) !important;
  transform: none !important;
  /* 尺寸 */
  width: var(--思维链宽度) !important;
  height: var(--思维链高度) !important;
  background: url("https://iili.io/q6DDY0v.png") center/contain no-repeat !important;
  border-radius: 0 !important;
  padding: 5px 10px !important;
  justify-content: center !important;
  align-items: center !important;
}

/* 隐藏原有箭头图标 */
.mes_reasoning_header.flex-container .mes_reasoning_arrow {
  display: none !important;
}

/* 思维链文字 */
.mes_reasoning_header_title {
  color: var(--color2) !important;
  /* 隐藏原有文字 */
  visibility: hidden !important;
  position: relative !important;
  width: 100% !important;
  text-align: center !important;
  /* 控制新文字大小 */
  font-size: var(--思维链文字大小) !important;
}

/* 思维链框 */
.mes_reasoning {
